let cache: PackedLocality[] | null = null

/** Parsed once per warm instance. */
export function localities(): PackedLocality[] {
  if (cache) return cache
  cache = PACKED.split(String.fromCharCode(10)).map((line) => {
    const [name, state, postcode, lat, lng] = line.split('|')
    return { name: name!, state: state!, postcode: postcode!, lat: Number(lat), lng: Number(lng) }
  })
  return cache
}
